import sys
from collections import defaultdict

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]

    if not lines:
        return

    bowlers = lines[:6]
    runs_data = lines[6:]

    runs = []
    for line in runs_data:
        parts = line.split()
        for part in parts:
            try:
                runs.append(int(part))
            except:
                pass

    if len(runs) != 36:
        return

    bowler_runs = defaultdict(int)
    for i in range(36):
        bowler = bowlers[i % 6]
        bowler_runs[bowler] += runs[i]

    max_runs = -1
    result = ""
    for bowler, total in bowler_runs.items():
        if total > max_runs:
            max_runs = total
            result = bowler

    print(result)

if __name__ == "__main__":
    main()
